#!/usr/bin/env python3
"""Emit webapp/frontend/js/snippets/*.r.txt — full plumber/viz cores, runnable under POST /api/exec/user_r."""
from __future__ import annotations

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PL = ROOT / "webapp" / "backend" / "plumber.R"
VZ = ROOT / "webapp" / "backend" / "helpers" / "viz.R"
OUT = ROOT / "webapp" / "frontend" / "js" / "snippets"

COMMON_HEAD = (
    "# Auto-generated by webapp/scripts/build_code_snippets.py\n"
    "# session_id (+ experiment) come from POST /api/user_r/run (Code Lab).\n"
)

JSON_LINE = re.compile(r"^\s*b\s*<-\s*jsonlite::fromJSON\(req\$postBody\)\s*$", re.MULTILINE)

EXP_GUARD = """if (!exists("experiment", inherits = FALSE) || is.null(experiment) || !nzchar(as.character(experiment)[1]))
  stop("experiment required: set in Code Lab or assign experiment <- 'YourExp'")
"""


def slurp(path: Path, lo: int, hi: int) -> str:
    lines = path.read_text(encoding="utf-8").splitlines()
    return "\n".join(lines[lo - 1 : hi]) + "\n"


def dedent_block(s: str) -> str:
    lines = s.splitlines()
    nonempty = [ln for ln in lines if ln.strip()]
    if not nonempty:
        return ""
    indents = [len(ln) - len(ln.lstrip(" ")) for ln in nonempty]
    m = min(indents)
    if m <= 0:
        return "\n".join(lines).rstrip() + "\n"
    out = []
    for ln in lines:
        if not ln.strip():
            out.append("")
        else:
            out.append(ln[m:] if len(ln) >= m else ln.lstrip())
    return "\n".join(out).rstrip() + "\n"


def strip_json_inject(s: str, b_prefix: str | None) -> str:
    s = dedent_block(s)
    s = JSON_LINE.sub("", s)
    if b_prefix:
        s = b_prefix.rstrip() + "\n" + s
    return s


def write(name: str, body: str, note: str) -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    head = COMMON_HEAD + f"# {note}\n\n"
    (OUT / name).write_text(head + body.rstrip() + "\n", encoding="utf-8")
    print("wrote", name)


