def clinical_overview_body() -> str:
    return (
        EXP_GUARD
        + "\n"
        + dedent_block(
            """
# --- GET /api/clinical/vars/:session_id/:experiment ---
df_exp <- list_clinical_vars(session_id, experiment)
out_exp <- list(success = TRUE, n_rows = nrow(df_exp), data = df_exp)

# --- GET /api/clinical/vars_standalone/:session_id ---
df_standalone <- list_clinical_vars_standalone(session_id)
out_standalone <- list(success = TRUE, n_rows = nrow(df_standalone), data = df_standalone)

list(experiment_vars = out_exp, standalone_vars = out_standalone)
"""
        )
    )


def tx_visual_bundle() -> str:
    exp = "as.character(experiment)[1]"
    b_h = f"""b <- list(
  session_id = session_id, experiment = {exp},
  group = NULL, top_n = 50L, features = NULL, cluster_rows = TRUE,
  cluster_cols = TRUE, show_gene_names = NULL, font_size = 11,
  color_panel = NULL, custom_colors = NULL
)
"""
    heatmap = strip_json_inject(slurp(PL, 1414, 1433), b_h)
    b_v = f"""b <- list(
  session_id = session_id, experiment = {exp},
  fc_cutoff = 1.0, p_cutoff = 0.05, color_panel = NULL, custom_colors = NULL
)
"""
    volcano = strip_json_inject(slurp(PL, 1442, 1452), b_v)
    return (
        EXP_GUARD
        + "\n# --- POST /api/workflows/transcriptomics/visualize/heatmap ---\n"
        + heatmap
        + "\n\n# --- POST /api/workflows/transcriptomics/visualize/volcano ---\n"
        + volcano
    )


