def tx_workflow_bundle() -> str:
    parts = [EXP_GUARD + "\n"]
    exp = "as.character(experiment)[1]"
    blocks: list[tuple[str, int, int, str]] = [
        (
            "POST /api/workflows/transcriptomics/profile",
            671,
            676,
            f"b <- list(session_id = session_id, experiment = {exp}, assay_hint = \"counts\")\n",
        ),
        ("POST /api/workflows/transcriptomics/validate", 685, 688, f"b <- list(session_id = session_id, experiment = {exp})\n"),
        (
            "POST /api/workflows/transcriptomics/analyze/differential",
            697,
            726,
            f"""b <- list(
  session_id = session_id, experiment = {exp}, method = "DESeq2",
  group_var = NULL, ref_group = NULL, test_group = NULL,
  filter_low = TRUE, subset_two_groups = TRUE, cores = "auto"
)
""",
        ),
        (
            "POST /api/workflows/transcriptomics/analyze/gsea",
            735,
            754,
            f"b <- list(session_id = session_id, experiment = {exp}, database = \"KEGG\", organism = \"hsa\")\n",
        ),
        (
            "POST /api/workflows/transcriptomics/analyze/wgcna",
            763,
            783,
            f"b <- list(session_id = session_id, experiment = {exp}, method = \"spearman\", cutoff = 0.7)\n",
        ),
    ]
    for title, lo, hi, bpre in blocks:
        core = strip_json_inject(slurp(PL, lo, hi), bpre)
        parts.append(f"# --- {title} ---\n{core}")
    return "\n\n".join(parts)


